<script setup lang="ts">
import {useHysRootAttrs} from '../../config'
const hysRootAttrs=useHysRootAttrs()
import {ref,computed,onDeactivated,onBeforeUnmount} from 'vue';const props=withDefaults(defineProps<{modelValue?:number;min?:number;max?:number;vertical?:boolean;disabled?:boolean}>(),{modelValue:40,min:15,max:85,vertical:false});const emit=defineEmits<{ 'update:modelValue':[value:number] }>();const host=ref<HTMLElement>();const size=computed(()=>Math.min(props.max,Math.max(props.min,props.modelValue)));let cleanup=()=>{};onDeactivated(()=>cleanup());onBeforeUnmount(()=>cleanup());function start(e:PointerEvent){cleanup();if(!host.value||props.disabled)return;const target=e.currentTarget as HTMLElement;target.setPointerCapture(e.pointerId);const rect=host.value.getBoundingClientRect();const move=(p:PointerEvent)=>{const v=props.vertical?(p.clientY-rect.top)/rect.height*100:(p.clientX-rect.left)/rect.width*100;emit('update:modelValue',Math.round(Math.max(props.min,Math.min(props.max,v))))};const end=()=>{target.removeEventListener('pointermove',move);target.removeEventListener('pointerup',end);target.removeEventListener('pointercancel',end);target.removeEventListener('lostpointercapture',end);cleanup=()=>{}};cleanup=end;target.addEventListener('lostpointercapture',end);target.addEventListener('pointermove',move);target.addEventListener('pointerup',end);target.addEventListener('pointercancel',end)}function key(e:KeyboardEvent){if(props.disabled)return;const step=e.shiftKey?10:2;if(['ArrowLeft','ArrowUp','ArrowRight','ArrowDown'].includes(e.key)){e.preventDefault();emit('update:modelValue',Math.max(props.min,Math.min(props.max,size.value+(['ArrowRight','ArrowDown'].includes(e.key)?step:-step))))}}
</script>
<template><div v-bind="hysRootAttrs" ref="host" class="hys-ui-ent-split" :class="{'hys-ui-vertical':vertical}" :style="{'--hys-ui-split':size+'%'}"><div class="hys-ui-ent-split-first"><slot name="first"/></div><div class="hys-ui-ent-split-handle" role="separator" :tabindex="disabled?-1:0" aria-label="调整面板比例" :aria-orientation="vertical?'horizontal':'vertical'" :aria-valuenow="size" :aria-valuemin="min" :aria-valuemax="max" @pointerdown="start" @keydown="key"/><div class="hys-ui-ent-split-second"><slot name="second"/></div></div></template>
